if(p==='/api/legal-documents'&&method==='POST'){let b=await parseBody(req),f=saveDataFile(b.data,b.name,'legal'),r=db.prepare('INSERT INTO legal_documents(title,category,filename,path,mime,created_at) VALUES(?,?,?,?,?,?)').run(b.title||b.name,b.category||'Agreement',f.filename,f.path,f.mime,now());return json(res,201,{id:Number(r.lastInsertRowid),...f})}
let ldm=p.match(/^\/api\/legal-documents\/(\d+)$/);if(ldm&&method==='DELETE'){let x=db.prepare('SELECT * FROM legal_documents WHERE id=?').get(+ldm[1]);if(x){try{fs.unlinkSync(path.join(ROOT,x.path.replace(/^\//,'')))}catch{}db.prepare('DELETE FROM legal_documents WHERE id=?').run(x.id)}return json(res,200,{ok:true})}

if(p==='/api/auth/login'&&method==='POST'){let b=await parseBody(req),x=db.prepare('SELECT * FROM users WHERE (email=? OR name=?) AND active=1').get((b.email||'').toLowerCase(),(b.email||'').trim());if(!x||!verify(b.password||'',x.password_hash))return json(res,401,{error:'Invalid email or password'});let t=crypto.randomBytes(32).toString('hex'),exp=new Date(Date.now()+7*864e5).toISOString();db.prepare('INSERT INTO sessions(token,user_id,expires_at,created_at) VALUES(?,?,?,?)').run(t,x.id,exp,now());audit(x,'login','session',t);return json(res,200,{token:t,user:{id:x.id,name:x.name,email:x.email,role:x.role}})}
if(p==='/api/auth/me')return u?json(res,200,u):json(res,401,{error:'Unauthorized'});
